function b({registerIndicator:f,sourceValues:m,nulls:y}){f({id:"oa-kri",name:"Kairi Relative Index (KRI)",category:"Oscillators",placement:"pane",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"period",type:"number",label:"Period",default:14,min:1,max:5e3,step:1,tooltip:"SMA lookback period."}],plots:[{key:"kri",type:"line",title:"KRI",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero",color:"#787b86",dashed:!0}],calc(o,a){const n=Math.max(1,Math.min(5e3,Math.floor(Number(a.period)||14))),c=m(o,a.source??"close"),s=new Array(n).fill(NaN);let t=0,l=0,u=0;const d=new Array(o.length).fill(NaN);for(let e=0;e<o.length;e++){const p=s[t];Number.isFinite(p)?l-=p:u+=1;const r=Number.isFinite(c[e])?c[e]:0;l+=r,s[t]=r,t=(t+1)%n;const i=l/Math.max(1,u);d[e]=i!==0?100*(r-i)/i:0}return{kri:y(d)}}})}export{b as default};
